/* 90_VERIFY — 읽기 전용. 기대: PACKAGE BODY VALID · 오류 0 · 표식 줄 2건(E20261124-DMF0082UCCUTOFF THEN 줄, 복원 주석 첫 줄) */
SELECT OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME, 'YYYY-MM-DD HH24:MI:SS') AS LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0082' ORDER BY 1;
SELECT COUNT(*) AS ERR_CNT FROM USER_ERRORS WHERE NAME = 'PKG_DMF0082';
SELECT LINE, TEXT FROM USER_SOURCE WHERE NAME = 'PKG_DMF0082' AND TYPE = 'PACKAGE BODY' AND (TEXT LIKE '%E20261124-DMF0082UCCUTOFF%' OR TEXT LIKE '%M3_CUTOFF_DATE%') ORDER BY LINE;
